('cur-es-de-ich weiß nicht.', 'es', 'de', 'Ich weiß nicht.', 'ich weiß nicht.', '', 'phrase', 'no sé', '["no lo sé"]', 'A1', '{"gender":null,"article":null,"plural":null,"genitive":null,"verb":null,"governs_case":null,"comparative":null,"superlative":null,"note":"También: Ich weiß es nicht (= no lo sé)."}', 'Wo ist mein Schlüssel? [[Ich weiß nicht]].', '¿Dónde está mi llave? [[No sé]].', 'curated', 3, 1795392000000),
