) v
JOIN entries e ON e.source_lang = 'es' AND e.target_lang = 'de' AND e.lemma_key = v.column3 AND e.sense_key = '';
-- Re-queue es -> de cards waiting for a meaning, so /generate looks them up in the dictionary again.
UPDATE cards SET status = 'pending', gen_error = NULL, gen_attempts = 0, gen_claimed_at = NULL,
  updated_at = CAST(strftime('%s','now') AS INTEGER) * 1000
WHERE status = 'failed' AND gen_error = 'needs_meaning' AND override_json IS NULL
  AND deck_id IN (SELECT id FROM decks WHERE source_lang = 'es' AND target_lang = 'de');
